import bisect

def max_sum_submatrix(matrix, k):
    rows, cols = len(matrix), len(matrix[0])
    best = float('-inf')
    for left in range(cols):
        row_sums = [0] * rows
        for right in range(left, cols):
            for r in range(rows):
                row_sums[r] += matrix[r][right]           # collapse this column range into one sum per row

            prefix = 0
            sorted_prefixes = [0]
            for s in row_sums:
                prefix += s
                idx = bisect.bisect_left(sorted_prefixes, prefix - k)  # smallest prefix >= prefix - k
                if idx < len(sorted_prefixes):
                    best = max(best, prefix - sorted_prefixes[idx])
                bisect.insort(sorted_prefixes, prefix)
    return best

