public class Main {
    static int maxSumSubmatrix(int[][] matrix, int k) {
        int rows = matrix.length, cols = matrix[0].length;
        int best = Integer.MIN_VALUE;
        for (int left = 0; left < cols; left++) {
            int[] rowSums = new int[rows];
            for (int right = left; right < cols; right++) {
                for (int r = 0; r < rows; r++) rowSums[r] += matrix[r][right];  // collapse into one sum per row

                TreeSet<Integer> prefixes = new TreeSet<>();
                prefixes.add(0);
                int prefix = 0;
                for (int s : rowSums) {
                    prefix += s;
                    Integer floorTarget = prefixes.ceiling(prefix - k);          // smallest prefix >= prefix - k
                    if (floorTarget != null) best = Math.max(best, prefix - floorTarget);
                    prefixes.add(prefix);
                }
            }
        }
        return best;
    }
}

