using namespace std;

int maxSumSubmatrix(vector<vector<int>>& matrix, int k) {
    int rows = matrix.size(), cols = matrix[0].size();
    int best = INT_MIN;
    for (int left = 0; left < cols; left++) {
        vector<int> rowSums(rows, 0);
        for (int right = left; right < cols; right++) {
            for (int r = 0; r < rows; r++) rowSums[r] += matrix[r][right];   // collapse into one sum per row

            set<int> prefixes = {0};
            int prefix = 0;
            for (int s : rowSums) {
                prefix += s;
                auto it = prefixes.lower_bound(prefix - k);                   // smallest prefix >= prefix - k
                if (it != prefixes.end()) best = max(best, prefix - *it);
                prefixes.insert(prefix);
            }
        }
    }
    return best;
}
